INSERT INTO `cpl` VALUES (1,1,'CPL01','Mampu menerapkan pengetahuan matematika, sains, dan prinsip rekayasa untuk menyelesaikan permasalahan di bidang sistem informasi.','Pengetahuan',70.00,'ACTIVE'),(2,1,'CPL02','Mampu mengidentifikasi, merumuskan, dan menganalisis permasalahan sistem informasi dengan pendekatan komputasi & perancangan arsitektur.','Keterampilan Umum',70.00,'ACTIVE'),(3,1,'CPL03','Mampu merancang, mengimplementasikan, dan mengevaluasi solusi perangkat lunak dan pemrograman sistem informasi yang handal.','Keterampilan Khusus',70.00,'ACTIVE'),(4,1,'CPL04','Mampu mengelola arsitektur basis data, memelihara integritas data, dan menyajikan dokumentasi teknis sistem informasi secara profesional.','Keterampilan Khusus',70.00,'ACTIVE'),(5,1,'CPL05','Mampu memimpin dan berkolaborasi dalam tim manajemen proyek sistem informasi dengan menunjukkan etika profesional dan tata kelola TI.','Sikap & Manajerial',70.00,'ACTIVE'),(6,1,'CPL06','Mampu menerapkan prinsip tata kelola keamanan informasi, manajemen risiko siber, dan audit kepatuhan dalam sistem enterprise.','Keterampilan Khusus',70.00,'ACTIVE');
/*!40000 ALTER TABLE `cpl` ENABLE KEYS */;
