INSERT INTO `cpmk` VALUES (27,5,'CPMK-1','Mampu menjelaskan konsep dasar sistem informasi dan perannya dalam transformasi organisasi.'),(28,5,'CPMK-2','Mampu menyusun analisis kebutuhan dan perancangan awal sistem informasi tingkat pemula.'),(29,6,'CPMK-1','Mampu menerapkan logika pemrograman dasar, tipe data, dan kontrol percabangan/perulangan.'),(30,6,'CPMK-2','Mampu merancang dan mengimplementasikan program modular berbasis fungsi untuk solusi sistem.'),(31,15,'CPMK-1','Mampu merancang model data konseptual dan logikal (ERD & Normalisasi 1NF-3NF).'),(32,15,'CPMK-2','Mampu mengimplementasikan struktur tabel dan query manipulasi data SQL kompleks pada RDBMS.'),(33,41,'CPMK-1','Mampu menyusun dokumen perencanaan proyek SI (Project Charter, WBS, Gantt Chart, Budgeting).'),(34,41,'CPMK-2','Mampu mengelola komunikasi tim, monitoring sprint agile, dan presentasi milestone proyek.'),(35,32,'CPMK-1','Mampu mengidentifikasi celah keamanan aplikasi web dan ancaman siber (OWASP Top 10).'),(36,32,'CPMK-2','Mampu merancang matriks risiko keamanan informasi (ISO 27001) dan rencana pemulihan bencana (DRP).'),(39,49,'CPMK 1','Mampu mengolah data dengan alat dan teknik pengolahan data (C3, A3, P3)'),(40,49,'CPMK 2','Mampu menganalisa data dengan alat dan teknik pengolahan data (C3, A3, P3)');
