INSERT INTO `cqi` VALUES (6,3,1,'Ganjil',70.00,66.80,'Rata-rata mahasiswa angkatan 2024 pada CPL03 berada di angka 66.8% (di bawah batas target mutu prodi 70%). Kesenjangan terbesar terlihat pada Sub-CPMK modularitas fungsi dan pemrograman terstruktur.','1. Mahasiswa kurang latihan coding mandiri di luar jam praktikum. 2. Perbedaan latar belakang kemampuan logika algoritma saat masuk prodi. 3. Sesi asistensi coding belum terjadwal rutin.','1. Mengadakan sesi Peer-Tutoring / Klinik Koding mingguan bersama asisten lab. 2. Mewajibkan 5 mini-project latihan mandiri di platform HackerRank/Git. 3. Merevisi rubrik asesmen agar memberikan bobot lebih pada unit-testing.','Tim Dosen KBK Rekayasa Perangkat Lunak','2026-12-15','Sesi klinik koding telah dimulai sejak minggu ke-4 dengan kehadiran rata-rata 85% mahasiswa yang memerlukan perbaikan.','IN_PROGRESS',NULL,'2026-09-20 07:03:58','2026-09-20 07:03:58'),(7,6,1,'Ganjil',70.00,64.50,'Pada evaluasi semester sebelumnya, capaian CPL06 hanya mencapai 64.5% akibat rendahnya skor unjuk kerja hands-on penanggulangan celah injeksi dan disaster recovery.','Lingkungan laboratorium keamanan siber belum memiliki mesin virtual (VM) terisolasi untuk simulasi serangan siber secara interaktif dan aman.','1. Menginstalasi server sandbox virtual lab siber (DVWA & WebGoat). 2. Mengintegrasikan studi kasus audit kerentanan ISO 27001 pada pertemuan ke-11 s.d. 13.','Andi Prasetyo, M.Kom. (Dosen Keamanan SI)','2026-10-30','Virtual lab telah aktif digunakan dan evaluasi siklus kedua selesai dilaksanakan.','RE_MEASURED',76.80,'2026-09-20 07:03:58','2026-09-20 07:03:58');
/*!40000 ALTER TABLE `cqi` ENABLE KEYS */;
UNLOCK TABLES;

